BEGIN TRANSACTION;
CREATE TABLE arrests(arrest_id INTEGER PRIMARY KEY, incident_id INTEGER REFERENCES incidents(incident_id), offender_id INTEGER REFERENCES offenders(offender_id), arrest_date TEXT, charge TEXT, disposition TEXT);
CREATE TABLE incidents(incident_id INTEGER PRIMARY KEY, report_date TEXT, offense_type TEXT, severity TEXT, district TEXT, location_type TEXT, weapon_involved INTEGER, status TEXT, officer_id INTEGER REFERENCES officers(officer_id));
CREATE TABLE offenders(offender_id INTEGER PRIMARY KEY, first_name TEXT, last_name TEXT, birth_date TEXT, sex TEXT, supervision_type TEXT, risk_level TEXT, prior_convictions INTEGER, home_district TEXT);
CREATE TABLE officers(officer_id INTEGER PRIMARY KEY, last_name TEXT, rank TEXT, district TEXT);
COMMIT;